"""Counting generated bytes and the cap implied by max_new_bytes (pure)."""

from __future__ import annotations

from collections.abc import Callable, Sequence

# A byte cap can cut a multi-byte UTF-8 character; the decoder then emits U+FFFD
# (3 bytes) for what is at most 3 real bytes, so allow that much slack.
CUT_CHAR_SLACK = 3


class AlignmentError(ValueError):
    """Raised when generate() output cannot be split reliably into prompt and new text."""


def is_bolmo_like(model: object) -> bool:
    """Byte-level latent-tokenizer models (Bolmo): their generate() counts bytes, see runner."""
    return hasattr(getattr(model, "model", None), "local_encoder")


def unit_of(model: object) -> str:
    return "bytes" if is_bolmo_like(model) else "tokens"


def cap_for(unit: str, max_new: int, *, max_token_bytes: int) -> int:
    """Largest number of new UTF-8 bytes a run may produce for max_new in `unit`."""
    if unit == "bytes":
        return max_new + CUT_CHAR_SLACK
    if unit == "tokens":
        return max_new * max_token_bytes
    raise ValueError(f"unknown unit {unit!r}")


def new_bytes(
    input_ids: Sequence[int],
    output_ids: Sequence[int],
    decode: Callable[[Sequence[int]], str],
) -> int:
    """UTF-8 bytes generated beyond the prompt.

    Requires the output to start with exactly the prompt ids and its decoded text to
    start with the decoded prompt; otherwise the split would be a guess.
    """
    n = len(input_ids)
    if len(output_ids) < n or list(output_ids[:n]) != list(input_ids):
        raise AlignmentError(
            f"output does not start with the {n} prompt ids; cannot split prompt from new text"
        )
    prompt_text = decode(input_ids)
    full_text = decode(output_ids)
    if not full_text.startswith(prompt_text):
        raise AlignmentError("decoded output does not start with the decoded prompt")
    return len(full_text.encode("utf-8")) - len(prompt_text.encode("utf-8"))


def first_divergence(a: bytes, b: bytes) -> int | None:
    """Index of the first byte where a and b differ; None if they are identical.

    If one is a strict prefix of the other, the divergence is at the shorter length.
    """
    n = min(len(a), len(b))
    for i in range(n):
        if a[i] != b[i]:
            return i
    return None if len(a) == len(b) else n
